static unsigned logic(unsigned s,unsigned d,unsigned op){switch(op){case 0:return 0;case 1:return s&d;case 2:return s&~d;case 3:return s;case 4:return ~s&d;case 5:return d;case 6:return s^d;case 7:return s|d;case 8:return ~(s|d);case 9:return ~(s^d);case 10:return ~d;case 11:return s|~d;case 12:return ~s;case 13:return ~s|d;case 14:return ~(s&d);default:return ~0u;}}
int main(){@autoreleasepool{
 id<MTLDevice> d=MTLCreateSystemDefaultDevice();NSError *e=nil;
 NSString *msl=@"#include <metal_stdlib>\nusing namespace metal;vertex float4 vs(uint i [[vertex_id]]){float2 p[]={float2(-1,-1),float2(3,-1),float2(-1,3)};return float4(p[i%3],0,1);}fragment float4 fs(float4 dst [[color(0)]], constant uint &op [[buffer(0)]]){uint4 s=uint4(60,165,112,204),d=uint4(round(dst*255.0)),r;switch(op){case 0:r=uint4(0);break;case 1:r=s&d;break;case 2:r=s&~d;break;case 3:r=s;break;case 4:r=~s&d;break;case 5:r=d;break;case 6:r=s^d;break;case 7:r=s|d;break;case 8:r=~(s|d);break;case 9:r=~(s^d);break;case 10:r=~d;break;case 11:r=s|~d;break;case 12:r=~s;break;case 13:r=~s|d;break;case 14:r=~(s&d);break;default:r=uint4(~0u);}return float4(r&255)/255.0;}";
 id<MTLLibrary> lib=[d newLibraryWithSource:msl options:nil error:&e];if(!lib){NSLog(@"%@",e);return 1;}MTLRenderPipelineDescriptor *pd=[MTLRenderPipelineDescriptor new];pd.vertexFunction=[lib newFunctionWithName:@"vs"];pd.fragmentFunction=[lib newFunctionWithName:@"fs"];pd.colorAttachments[0].pixelFormat=MTLPixelFormatRGBA8Unorm;
 id<MTLRenderPipelineState> p=[d newRenderPipelineStateWithDescriptor:pd error:&e];if(!p){NSLog(@"%@",e);return 2;}
