 for(unsigned op=0;op<16;op++){id<MTLCommandBuffer> c=[q commandBuffer];MTLRenderPassDescriptor *pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.colorAttachments[0].texture=t;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;pass.colorAttachments[0].clearColor=MTLClearColorMake(seed[0]/255.,seed[1]/255.,seed[2]/255.,seed[3]/255.);id<MTLRenderCommandEncoder> r=[c renderCommandEncoderWithDescriptor:pass];[r setRenderPipelineState:p];[r setFragmentBytes:&op length:4 atIndex:0];[r drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:6];[r endEncoding];[c commit];[c waitUntilCompleted];if(c.error){NSLog(@"%@",c.error);return 3;}unsigned char pixels[256];[t getBytes:pixels bytesPerRow:32 fromRegion:MTLRegionMake2D(0,0,8,8) mipmapLevel:0];for(unsigned i=0;i<256;i++){unsigned k=i%4,expected=logic(s[k],logic(s[k],seed[k],op)&255,op)&255;if(pixels[i]!=expected){printf("FAIL op=%u pixel=%u got=%u want=%u\n",op,i,pixels[i],expected);return 4;}tested++;}}
 printf("logic-fetch-ok: %u exact components across 16 operations, two overlapping primitives\n",tested);return 0;
